# Find active row
def find_active_row(grid):
    for r_idx in range(len(grid)-1, -1, -1):
        for val in grid[r_idx]:
            if val != 0:
                return grid[r_idx], r_idx
    return None, None

# Build output grid
def transform(grid):
    active_row, active_row_idx = find_active_row(grid)
    if active_row is None:
        return grid

    h, w = len(grid), len(grid[0])
    output = [[0]*w for _ in range(h)]

    # Copy active row
    for c in range(w):
        output[active_row_idx][c] = active_row[c]

    # For each column, find if it has special values (2 or 8)
    special_cols = {}
    for c, val in enumerate(active_row):
        if val == 2 or val == 8:
            special_cols[c] = val

    # Fill columns with special values
    for col, val in special_cols.items():
        # Top marker position
        # From demo: val=2 -> top at row-4, val=8 -> top at row-3
        # Distance from active row = 4 for val=2, 3 for val=8
        # Let's use: distance = (val == 2 ? 4 : 3)
        if val == 2:
            top_row = active_row_idx - 4
        else:  # val == 8
            top_row = active_row_idx - 3

        # Fill with 1s between top and active, except at top and active
        if top_row >= 0:
            for r in range(top_row + 1, active_row_idx):
                output[r][col] = 1

    return output

