def column_segments(col_idx, grid):
    """Find segments of consecutive non-zero values in a column"""
    segments = []
    r = 0
    while r < len(grid):
        if grid[r][col_idx] != 0:
            end = r
            while end < len(grid) and grid[end][col_idx] != 0:
                end += 1
            segments.append((r, end-1, [grid[i][col_idx] for i in range(r, end)]))
            r = end
        else:
            r += 1
    return segments

